function read(k,fallback){try{return JSON.parse(localStorage.getItem('circuit-demo-'+k))??fallback}catch{return fallback}}
let loginReturn='/account',checkoutDraft={},filtersOpen=false;
let products=read('products',baseProducts),cart=read('cart',[]),wishlist=read('wishlist',[]),orders=read('orders',[seedOrder]),profile=read('profile',{name:'Vikram Kumar',email:'customer@powerelectronics.demo',phone:'9000000000',address:'12 Demo Avenue',city:'Hyderabad',state:'Telangana',pincode:'500032'}),coupon=read('coupon',''),user=null,homeTab='Bestsellers',adminTab='Overview',accountTab='Orders',detailQty=1;
try{user=JSON.parse(sessionStorage.getItem('circuit-demo-user'))}catch{}
const $=s=>document.querySelector(s),money=n=>'₹'+Number(n).toLocaleString('en-IN',{minimumFractionDigits:Number.isInteger(Number(n))?0:2,maximumFractionDigits:2}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),product=id=>products.find(p=>p.id===Number(id)),img=id=>{const p=product(id);return p?.imageData&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(p.imageData)?p.imageData:p?.imageUrl?safeImageUrl(p.imageUrl):`/assets/product-${p?.assetId||id}.webp`};
// Preserve earlier demo records and sessions after the brand rename.
for(const o of orders)o.email=o.email.replace('@circuit.demo','@powerelectronics.demo');
profile.email=profile.email.replace('@circuit.demo','@powerelectronics.demo');
if(user){user.email=user.email.replace('@circuit.demo','@powerelectronics.demo');sessionStorage.setItem('circuit-demo-user',JSON.stringify(user))}
function save(){for(const [k,v] of Object.entries({products,cart,wishlist,orders,profile,coupon}))try{localStorage.setItem('circuit-demo-'+k,JSON.stringify(v))}catch{};updateHeader();syncCardControls()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function updateHeader(){$('#cartcount').textContent=cart.reduce((a,i)=>a+i.qty,0);$('#accountbutton').innerHTML=icon('user')+`<span class="desktop">${user?esc(user.role==='admin'?'Admin':profile.name.split(' ')[0]):'Account'}</span>`}
$('#hearticon').innerHTML=icon('heart');$('#carticon').innerHTML=icon('cart');
// Keep existing demo orders stable when catalog names change.
for(const o of orders)for(const item of o.items)if(!item.name)item.name=product(item.id)?.name||'Component';
function totals(){const subtotal=cart.reduce((a,i)=>a+product(i.id).price*i.qty,0),discount=coupon==='BUILD10'?Math.round(subtotal*.1):0,shipping=subtotal===0||subtotal>=999?0:59;return {subtotal,discount,shipping,total:subtotal-discount+shipping}}
function addToCart(id,qty=1){const p=product(id);if(!p||p.active===false)throw Error('Product is unavailable');if(!Number.isInteger(qty)||qty<1||qty>99)throw Error('Quantity must be between 1 and 99');const existing=cart.find(i=>i.id===p.id);if((existing?.qty||0)+qty>99){toast('Maximum 99 units per product');return false}if((existing?.qty||0)+qty>p.stock){toast(p.stock?'Maximum available quantity reached':'This product is sold out');return false}if(existing)existing.qty+=qty;else cart.push({id:p.id,qty});save();toast(`${p.name} added to cart`);return true}

function cardCartControl(p){const qty=cart.find(i=>i.id===p.id)?.qty||0;if(!qty)return `<button class="add-btn" data-action="add" data-id="${p.id}" ${!p.stock?'disabled':''}>${icon('plus',14)} ${p.stock?'Add to cart':'Out of stock'}</button>`;return `<div class="card-quantity" role="group" aria-label="Cart quantity for ${esc(p.name)}"><button data-action="card-qty" data-id="${p.id}" data-change="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span aria-live="polite">${qty}</span><button data-action="card-qty" data-id="${p.id}" data-change="1" aria-label="Increase ${esc(p.name)} quantity" ${qty>=Math.min(99,p.stock)?'disabled':''}>+</button></div>`}
function syncCardControls(){for(const el of document.querySelectorAll?.('[data-cart-control]')||[]){const p=product(el.dataset.cartControl);if(p)el.innerHTML=cardCartControl(p)}}
function changeCardQuantity(id,change){const item=cart.find(i=>i.id===Number(id));if(!item)return;if(change!==1&&change!==-1)return;if(item.qty+change>Math.min(99,product(id).stock)){toast('Maximum available quantity reached');return}item.qty+=change;cart=cart.filter(i=>i.qty>0);save();toast(item.qty?`Cart quantity updated to ${item.qty}`:'Removed from cart')}
const storeOrigin=window.location?.origin||location.origin;
function shareInfo(id){const p=id?product(id):null;if(id&&!p)throw Error('Product not found');return {title:p?`${p.name} | Power Electronics`:'Power Electronics',text:p?`${p.name} — ${money(p.price)} at Power Electronics`:'Explore electronics components at Power Electronics.',url:storeOrigin+(p?`/#/product/${p.id}`:'/#/')}}
let pendingShare=null;
function openShare(id){pendingShare=shareInfo(id);const data=pendingShare,encoded=encodeURIComponent(data.text+' '+data.url),url=encodeURIComponent(data.url);showModal(`<div class="eyebrow">Share a great find</div><h2>${id?'Share this product':'Share Power Electronics'}</h2><p>${esc(data.title)}</p><div class="share-grid"><a class="share-option whatsapp" href="https://wa.me/?text=${encoded}" target="_blank" rel="noopener noreferrer">WhatsApp</a><a class="share-option" href="https://www.facebook.com/sharer/sharer.php?u=${url}" target="_blank" rel="noopener noreferrer">Facebook</a><a class="share-option" href="https://www.linkedin.com/sharing/share-offsite/?url=${url}" target="_blank" rel="noopener noreferrer">LinkedIn</a><a class="share-option" href="https://t.me/share/url?url=${url}&text=${encodeURIComponent(data.text)}" target="_blank" rel="noopener noreferrer">Telegram</a><button class="share-option" data-action="copy-share">Copy link</button>${typeof navigator!=='undefined'&&navigator.share?'<button class="share-option" data-action="native-share">More options</button>':''}</div><label class="field">Share link<input id="shareurl" readonly value="${esc(data.url)}" aria-label="Link to share"></label><p class="subtle">Share the link to open this product or storefront.</p>`)}
async function copyShare(){if(!pendingShare)return;try{await navigator.clipboard.writeText(pendingShare.url);toast('Link copied')}catch{const field=$('#shareurl');field.focus();field.select();toast('Select and copy the highlighted link')}}
async function nativeShare(){if(!pendingShare||!navigator.share)return;try{await navigator.share(pendingShare)}catch(error){if(error.name!=='AbortError')toast('Sharing unavailable. Use Copy link instead.')}}

function card(p){return `<article class="product" data-product-card="${p.id}"><span class="badge ${p.tag==='Bestseller'||p.tag==='New arrival'?'mint':''}">${esc(p.stock?p.tag:'Out of stock')}</span><button class="wishlist-button ${wishlist.includes(p.id)?'selected':''}" data-action="wish" data-id="${p.id}" aria-label="${wishlist.includes(p.id)?'Remove from':'Add to'} wishlist" aria-pressed="${wishlist.includes(p.id)}">${icon('heart',16)}</button><a href="#/product/${p.id}" class="product-image"><img src="${img(p.id)}" alt="${esc(p.name)}" width="230" height="195" loading="lazy"></a><div class="meta">${esc(p.category)}</div><h3><a href="#/product/${p.id}">${esc(p.name)}</a></h3><p class="product-desc">${esc(p.desc)}</p><div class="rating">${p.reviews?`<span class="stars">★★★★★</span> ${p.rating} <span>(${p.reviews})</span>`:'New in the catalog'}</div><div class="product-bottom"><div class="price">${money(p.price)} <span class="old">${money(p.old)}</span></div><div class="cart-control" data-cart-control="${p.id}">${cardCartControl(p)}</div></div>${priceUpdatedNotice(p.id)}${stockRequestCTA(p)}<div class="product-utilities"><div class="stock ${!p.stock?'out':''}">${p.stock?'In stock · Ready to ship':'Out of stock'}</div><button class="product-share" data-action="share" data-id="${p.id}" aria-label="Share ${esc(p.name)}">${icon('share',16)}</button></div></article>`}
function crumbs(label){return `<div class="breadcrumb"><a href="#/">Home</a> <span class="sep">/</span> ${esc(label)}</div>`}
function empty(title,text,cta='Browse products'){return `<div class="empty">${icon('box',40)}<h2>${title}</h2><p>${text}</p><a href="#/shop" class="btn">${cta}</a></div>`}
function home(){let list=homeTab==='New arrivals'?[...products.filter(p=>p.origin==='excel-import').reverse(),...products.slice(4,12)].slice(0,8):homeTab==='Best deals'?[...products].sort((a,b)=>(1-b.price/b.old)-(1-a.price/a.old)).slice(0,8):[products[0],products[3],products[1],products[2],products[7],products[8],products[9],products[4]];return `<div class="wrap home"><div class="hero-layout"><section class="hero"><div class="hero-copy"><div class="eyebrow">For the ideas you can't wait to build</div><h1>Your one-stop<br>electronics market.</h1><p>From your first circuit to your next breakthrough. Find the right parts, right here.</p><a href="#/shop" class="btn btn-dark">Explore components</a></div><div class="hero-art"><img src="${img(2)}" alt="Raspberry Pi 4 development board" width="360" height="300" fetchpriority="high"><div class="art-label"><strong>Raspberry Pi 4</strong>More power for your next idea.</div></div></section><section class="hero-side"><div class="eyebrow">The connected collection</div><h2>Your next IoT<br>project starts here.</h2><p>Meet your go-to ESP32 boards.</p><img src="${img(4)}" alt="ESP32 development board" width="145" height="125"><a href="#/product/4" class="btn">Discover ESP32</a></section></div><div class="benefits">${[['truck','Delivered across India','Free shipping above ₹999'],['shield','Quality you can trust','Carefully selected components'],['box','Easy 7-day returns','Simple, hassle-free support'],['support','Made for makers','Help finding your next part']].map(x=>`<div class="benefit">${icon(x[0],29)}<div><strong>${x[1]}</strong><small>${x[2]}</small></div></div>`).join('')}</div><section class="section"><div class="section-head"><h2>Find your building blocks</h2><a href="#/shop" class="text-link">View all categories</a></div><div class="categories">${categories.map(([c,id])=>`<a class="category" href="#/shop?category=${encodeURIComponent(c)}"><img src="${img(id)}" alt="" width="110" height="72"><strong>${esc(c)}</strong><small>${products.filter(p=>p.category===c).length} products</small></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><h2>Maker favourites</h2><p>Reliable parts. Ready for your next project.</p></div><div class="tabs" aria-label="Product collections">${['Bestsellers','New arrivals','Best deals'].map(t=>`<button data-action="home-tab" data-tab="${t}" class="${homeTab===t?'active':''}" aria-pressed="${homeTab===t}">${t}</button>`).join('')}</div></div><div class="products">${list.map(card).join('')}</div></section><section class="wide-promo"><div><div class="eyebrow" style="color:var(--mint);margin-bottom:10px">A little boost for your next build</div><h2>Your ideas deserve a head start.</h2><p>Save 10% on your order with <b>BUILD10</b>. One more reason to start creating.</p></div><a href="#/shop?deal=1" class="btn">Shop the deals</a></section></div>`}
function shop(q){let cat=q.get('category')||'',term=q.get('q')||'',sort=q.get('sort')||'popular',max=Number(q.get('max'))||10000,instock=q.get('stock')==='1';const filtered=products.filter(p=>(!cat||p.category===cat)&&(!term||`${p.name} ${p.category} ${p.desc}`.toLowerCase().includes(term.toLowerCase()))&&p.price<=max&&(!instock||p.stock>0));if(sort==='low')filtered.sort((a,b)=>a.price-b.price);if(sort==='high')filtered.sort((a,b)=>b.price-a.price);if(sort==='rating')filtered.sort((a,b)=>b.rating-a.rating);if(q.has('deal')&&sort==='popular')filtered.sort((a,b)=>(1-b.price/b.old)-(1-a.price/a.old));return `<div class="wrap">${crumbs('Shop')}<div class="page-title"><h1>${term?'Results for “'+esc(term)+'”':cat?esc(cat):q.has('deal')?'Deals for your next build':'Everything for your next build'}</h1><p>Explore boards, sensors and the little things that make big ideas work.</p></div><div class="shop-layout"><aside class="filter-shell"><button class="mobile-filter-toggle" data-action="toggle-filters" aria-controls="product-filters" aria-expanded="${filtersOpen}"><span>Filter products</span><span>${filtersOpen?'Close':'Show filters'}</span></button><div id="product-filters" class="filters ${filtersOpen?'open':''}"><h3>Filter products</h3><div class="filter-group"><h3>Category</h3>${[['All categories',''],...categories.map(c=>[c[0],c[0]])].map(([name,c])=>`<label class="filter-choice"><input type="radio" name="category" data-filter="category" value="${esc(c)}" ${cat===c?'checked':''}>${esc(name)}<span>${c?products.filter(p=>p.category===c).length:products.length}</span></label>`).join('')}</div><div class="filter-group price-filter"><h3>Maximum price</h3><input type="range" id="pricerange" data-filter="max" min="50" max="10000" step="50" value="${max}" aria-label="Maximum product price"><div class="toolbar"><span>₹50</span><span>${money(max)}</span></div></div><div class="filter-group"><label class="filter-choice"><input type="checkbox" data-filter="stock" ${instock?'checked':''}> In stock only</label><button class="filter-reset" data-action="clear-filters">Clear filters</button></div></div></aside><section><div class="toolbar"><span>${filtered.length} products ${cat?'in '+esc(cat):''}</span><label>Sort by <select data-filter="sort" aria-label="Sort products">${[['popular','Recommended'],['low','Price: low to high'],['high','Price: high to low'],['rating','Highest rated']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${filtered.length?`<div class="products">${filtered.map(card).join('')}</div>`:empty('No components found','Try another search or clear your filters.')}</section></div></div>`}
function detail(id){const p=product(id);if(!p)return `<div class="wrap">${crumbs('Product')}${empty('Product not found','Explore the rest of the catalog.')}</div>`;return `<div class="wrap">${crumbs(p.category)}<div class="detail-layout"><div class="detail-image"><img src="${img(p.id)}" alt="${esc(p.name)}" width="450" height="380"></div><div class="detail-copy"><div class="eyebrow">${esc(p.category)}</div><h1>${esc(p.name)}</h1><div class="rating">${p.reviews?`<span class="stars">★★★★★</span> ${p.rating} · ${p.reviews} sample reviews`:'New in the catalog'}</div><div class="price">${money(p.price)} <span class="old">${money(p.old)}</span></div>${priceUpdatedNotice(p.id)}<div class="stock ${p.stock?'':'out'}">${p.stock?p.stock+' units in stock':'Out of stock'} · Sample price includes tax</div><p>${esc(p.desc)}. A practical choice for learning, prototyping and bringing your electronics project to life. Check the specifications below to find the right fit for your build.</p><div class="detail-cta"><div class="qty"><button data-action="detail-qty" data-change="-1" aria-label="Decrease quantity">−</button><span id="detailqty">${detailQty}</span><button data-action="detail-qty" data-change="1" aria-label="Increase quantity">+</button></div><button class="btn" data-action="add-detail" data-id="${p.id}" ${!p.stock?'disabled':''}>${icon('cart',18)} Add to cart</button><button class="btn btn-outline" data-action="wish" data-id="${p.id}" aria-label="Toggle wishlist" aria-pressed="${wishlist.includes(p.id)}">${icon('heart',18)}</button></div>${stockRequestCTA(p)}<div class="saved-note">Free delivery on orders over ₹999 · 7-day return window</div><button class="btn btn-outline detail-share" data-action="share" data-id="${p.id}">${icon('share',17)} Share product</button><p class="subtle">SKU: ${esc(p.sku||'CT-'+String(p.id).padStart(4,'0'))} · Photos from the reference catalog. Specifications and availability are sample data.</p></div></div><section class="section"><div class="section-head"><h2>Technical specifications</h2></div><table class="specs"><tbody>${Object.entries(p.specs).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></section><section class="section"><div class="section-head"><h2>You might also need</h2></div><div class="products">${products.filter(x=>x.id!==p.id&&x.stock>0).slice(0,4).map(card).join('')}</div></section></div>`}
function summary(checkout=false){const t=totals();return `<aside class="panel summary"><h3>Order summary</h3>${checkout?cart.map(i=>`<div class="summary-line"><span>${esc(product(i.id).name)} × ${i.qty}</span><b>${money(product(i.id).price*i.qty)}</b></div>`).join(''):''}<div class="summary-line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="summary-line"><span>Delivery</span><span class="check">${t.shipping?money(t.shipping):'Free'}</span></div>${t.discount?`<div class="summary-line"><span>BUILD10 discount</span><span class="check">−${money(t.discount)}</span></div>`:''}<form id="couponform" class="coupon"><input name="code" placeholder="Discount code" value="${esc(coupon)}" aria-label="Discount code"><button class="btn btn-outline btn-small">Apply</button></form><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div><p class="subtle">Sample prices include tax.${t.shipping?' Add '+money(999-t.subtotal)+' more for free delivery.':''}</p>${!checkout?'<a href="#/checkout" class="btn">Continue to checkout</a>':''}<p class="subtle">${icon('shield',14)} Demo checkout · No real charges</p></aside>`}
function cartPage(){return `<div class="wrap">${crumbs('Cart')}<div class="page-title"><h1>Your cart</h1><p>${cart.reduce((n,i)=>n+i.qty,0)} components, one step closer to your next idea.</p></div>${cart.length?`<div class="two-columns"><section class="panel">${cart.map(i=>{const p=product(i.id);return `<div class="cart-row"><a href="#/product/${p.id}"><img src="${img(p.id)}" alt="${esc(p.name)}"></a><div><h3><a href="#/product/${p.id}">${esc(p.name)}</a></h3><div class="subtle" style="margin:0">${money(p.price)} each · ${esc(p.desc)}</div><div class="qty"><button data-action="cart-qty" data-id="${p.id}" data-change="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${i.qty}</span><button data-action="cart-qty" data-id="${p.id}" data-change="1" aria-label="Increase ${esc(p.name)} quantity">+</button></div></div><div><b>${money(p.price*i.qty)}</b><br><button class="remove" data-action="remove" data-id="${p.id}">Remove</button></div></div>`}).join('')}<a class="text-link" href="#/shop" style="display:block;margin-top:24px">Continue shopping</a></section>${summary()}</div>`:empty('Your cart is waiting for an idea','Pick a few components to get your next build started.')}</div>`}
function checkout(){const delivery={...profile,...checkoutDraft};if(!cart.length)return `<div class="wrap">${crumbs('Checkout')}${empty('Your cart is empty','Add a product before checking out.')}</div>`;return `<div class="wrap">${crumbs('Checkout')}<div class="page-title"><h1>One step closer to your next build.</h1><p>Demo checkout. Please use sample contact and delivery details.</p></div><div class="two-columns"><form id="checkoutform" class="panel checkout"><h3>Delivery information</h3>${!user?'<div class="saved-note">Have an account? <button type="button" class="filter-reset" data-action="login">Sign in</button> to view your demo orders later. Guest checkout is also available.</div>':''}<div class="form-grid">${field('Full name','name',delivery.name,'text',true)}${field('Email address','email',delivery.email,'email',true)}${field('Phone number','phone',delivery.phone,'tel',true,'[0-9]{10}')} ${field('PIN code','pincode',delivery.pincode,'text',true,'[1-9][0-9]{5}')}<label class="field full">Street address<input name="address" required value="${esc(delivery.address)}" maxlength="180"></label>${field('City','city',delivery.city,'text',true)}${field('State','state',delivery.state,'text',true)}</div><h3>Payment method</h3><div class="payment-options"><label class="payment-option"><input type="radio" name="payment" value="Demo UPI" ${delivery.payment!=='Demo cash on delivery'?'checked':''}><span><b>UPI — demo</b><br><small>No UPI app opens and no money is collected.</small></span></label><label class="payment-option"><input type="radio" name="payment" value="Demo cash on delivery" ${delivery.payment==='Demo cash on delivery'?'checked':''}><span><b>Cash on delivery — demo</b><br><small>Creates a sample order only. Nothing is shipped.</small></span></label></div><label class="filter-choice"><input type="checkbox" name="acknowledge" required ${delivery.acknowledge?'checked':''}> I understand this is a demo order with no payment or shipment.</label><button class="btn" style="width:100%;margin-top:20px">Place demo order · ${money(totals().total)}</button><p id="checkout-error" class="error" role="alert"></p></form>${summary(true)}</div></div>`}
function field(label,name,value='',type='text',required=false,pattern=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${pattern?`pattern="${pattern}" title="${name==='phone'?'Enter a 10-digit phone number':'Enter a valid 6-digit Indian PIN code'}"`:''} maxlength="100"></label>`}
function success(id){const o=orders.find(o=>o.id===id);if(!o)return `<div class="wrap">${empty('Order not found','Your saved orders are available in your account.')}</div>`;return `<div class="wrap"><div class="success"><div class="success-mark">✓</div><h1 style="font-size:34px;letter-spacing:-1px">Your demo order is confirmed.</h1><p>Thanks for building with Power Electronics. Order <b>${esc(o.id)}</b> has been added to the demo. No payment was taken and no items will be shipped.</p><div class="panel" style="max-width:500px;margin:0 auto 25px;text-align:left"><div class="summary-line"><span>Order total</span><b>${money(o.total)}</b></div><div class="summary-line"><span>Payment method</span><b>${esc(o.payment)}</b></div><div class="summary-line"><span>Status</span><span class="status processing">${esc(o.status)}</span></div></div><a href="#/shop" class="btn">Continue exploring</a> <a href="#/account" class="btn btn-outline">View orders</a></div></div>`}
function orderCard(o){return `<article class="order-card"><div class="order-head"><div><b>${esc(o.id)}</b><p>${new Date(o.date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · ${o.items.reduce((a,i)=>a+i.qty,0)} items · ${money(o.total)}</p></div><span class="status ${o.status!=='Delivered'?'processing':''}">${esc(o.status)}</span></div>${o.items.map(i=>`<div class="order-items" style="margin:10px 0"><img src="${img(i.id)}" alt="${esc(i.name||product(i.id)?.name)}"><div>${esc(i.name||product(i.id)?.name)}<div class="subtle" style="margin:3px 0">Qty: ${i.qty} · ${money(i.price*i.qty)}</div></div></div>`).join('')}<p class="subtle">${esc(o.address)}</p></article>`}
function account(){if(!user)return `<div class="wrap">${crumbs('Account')}<div class="success"><div class="success-mark">${icon('user',32)}</div><h2>Your builds, all in one place.</h2><p>Sign in to your demo customer account to view orders and update your profile.</p><button class="btn" data-action="login">Customer sign in</button><button class="btn btn-outline" data-action="admin-login">Admin sign in</button></div></div>`;if(user.role==='admin')return admin();const mine=orders.filter(o=>o.email===user.email);return `<div class="wrap">${crumbs('Your account')}<div class="page-title"><h1>Hello, ${esc(profile.name.split(' ')[0])}.</h1><p>Your next great idea starts here.</p></div><div class="account-layout"><aside class="side-menu"><div class="profile-card"><div class="avatar">${esc(profile.name.slice(0,1))}</div><b>${esc(profile.name)}</b><p>${esc(user.email)}</p></div>${['Orders','Profile'].map(t=>`<button data-action="account-tab" data-tab="${t}" class="${accountTab===t?'active':''}">${t}</button>`).join('')}<a href="#/bulk-orders">Bulk orders</a><a href="#/stock-requests">Stock requests</a><a href="#/notifications">Notifications</a><a href="#/wishlist">Wishlist (${wishlist.length})</a><button data-action="logout">Sign out</button></aside><section>${accountTab==='Orders'?`<div class="section-head"><h2>Your orders</h2><span class="subtle">${mine.length} orders</span></div>${mine.length?mine.map(orderCard).join(''):empty('No orders yet','Your demo orders will appear here after checkout.')}`:`<div class="panel"><h2 style="font-size:23px;margin-bottom:22px">Your profile</h2><form id="profileform"><div class="form-grid">${field('Full name','name',profile.name,'text',true)}${field('Phone number','phone',profile.phone,'tel',true,'[0-9]{10}')}${field('Street address','address',profile.address,'text',true)}${field('City','city',profile.city,'text',true)}${field('State','state',profile.state,'text',true)}${field('PIN code','pincode',profile.pincode,'text',true,'[1-9][0-9]{5}')}</div><p class="subtle" style="margin:0 0 20px">Demo email: ${esc(user.email)}</p><button class="btn">Save profile</button></form></div>`}</section></div></div>`}
function admin(){if(user?.role!=='admin')return `<div class="wrap">${crumbs('Admin')}<div class="success"><h2>Store administration</h2><p>Sign in with the demo administrator account to explore products, orders and inventory.</p><button class="btn" data-action="admin-login">Admin sign in</button></div></div>`;const revenue=orders.filter(o=>o.status!=='Cancelled').reduce((a,o)=>a+o.total,0);return `<div class="admin-shell"><div class="wrap"><div class="admin-heading"><div><div class="eyebrow">Power Electronics administration</div><h1>Your store, at a glance.</h1><p>Welcome back, Alex. Here's how your demo store is doing.</p></div><button class="btn btn-outline" data-action="logout">Sign out</button></div><div class="saved-note">Demo workspace · All edits and orders are stored in this browser. This preview is not a secure production admin system.</div><div class="metrics">${[['Total revenue',money(revenue),'Sample orders'],['Orders',orders.length,orders.filter(o=>o.status==='Processing').length+' to process'],['Products',products.length,'Across '+categories.length+' categories'],['Low stock',products.filter(p=>p.stock<10).length,'Under 10 units']].map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div><div class="admin-tabs">${['Overview','Products','Orders','Customers'].map(t=>`<button data-action="admin-tab" data-tab="${t}" class="${adminTab===t?'active':''}">${t}</button>`).join('')}<a class="btn btn-outline" href="#/admin/settings">Settings</a><a class="btn btn-outline" href="#/admin/bulk-orders">Bulk orders</a><a class="btn btn-outline" href="#/admin/stock-requests">Stock requests</a><a class="btn btn-outline" href="#/admin/pricing">Pricing & stock</a><a class="btn btn-outline" href="#/admin/price-history">Price history</a><a class="btn btn-outline" href="#/admin/upload">Upload Excel</a><a class="btn btn-outline" href="#/admin/uploads">Uploaded items</a><a class="btn btn-outline" href="#/shop" style="margin-left:auto">View storefront</a></div>${adminTab==='Overview'?`<div class="activity-grid"><section class="panel"><div class="section-head"><h3>Sales activity</h3><span class="subtle" style="margin:0">Illustrative weekly trend</span></div><div class="bar-chart" role="img" aria-label="Illustrative sample sales chart Monday through Sunday">${[45,68,50,82,62,95,73].map((v,i)=>`<div class="bar-group"><div class="bar" style="height:${v}%"></div><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}</div></section><section class="panel"><h3>Needs your attention</h3>${products.filter(p=>p.stock<10).map(p=>`<div class="low-stock"><span>${esc(p.name)}<br><small class="subtle">${p.stock?'Only '+p.stock+' remaining':'Out of stock'}</small></span><button class="btn btn-outline btn-small" data-action="edit-product" data-id="${p.id}">Edit</button></div>`).join('')}</section></div><section class="panel" style="margin-top:22px"><div class="section-head"><h3>Recent orders</h3><button class="filter-reset" data-action="admin-tab" data-tab="Orders">View all orders</button></div>${ordersTable(orders.slice(0,5))}</section>`:adminTab==='Products'?`<section class="panel"><div class="section-head"><h3>Products & inventory</h3><span class="subtle" style="margin:0">${products.length} products</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Action</th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="table-product"><img src="${img(p.id)}" alt=""><b>${esc(p.name)}</b></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td><span class="${p.stock<10?'out':'check'}">${p.stock} units</span></td><td><button class="btn btn-outline btn-small" data-action="edit-product" data-id="${p.id}">Edit</button><button class="filter-reset stock-single" data-admin-feature="toggle-active" data-id="${p.id}">${p.active===false?'Activate':'Deactivate'}</button><span class="catalog-state ${p.active===false?'inactive':'active'}">${p.active===false?'Inactive':'Active'}</span>${p.stock?`<button class="filter-reset stock-single" data-experience="single-out" data-id="${p.id}">Mark out of stock</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`:adminTab==='Orders'?`<section class="panel"><div class="section-head"><h3>Manage orders</h3><span class="subtle" style="margin:0">Update sample order status</span></div>${ordersTable(orders)}</section>`:`<section class="panel"><h3 style="margin-bottom:20px">Demo customers</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Customer</th><th>Email</th><th>Orders</th><th>Total spent</th></tr></thead><tbody><tr><td>${esc(profile.name)}</td><td>customer@powerelectronics.demo</td><td>${orders.filter(o=>o.email==='customer@powerelectronics.demo').length}</td><td>${money(orders.filter(o=>o.email==='customer@powerelectronics.demo').reduce((a,o)=>a+o.total,0))}</td></tr>${[...new Set(orders.map(o=>o.email))].filter(e=>e!=='customer@powerelectronics.demo').map(e=>`<tr><td>Guest customer</td><td>${esc(e)}</td><td>${orders.filter(o=>o.email===e).length}</td><td>${money(orders.filter(o=>o.email===e).reduce((a,o)=>a+o.total,0))}</td></tr>`).join('')}</tbody></table></div></section>`}</div></div>`}
function ordersTable(list){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Details</th></tr></thead><tbody>${list.map(o=>`<tr><td><b>${esc(o.id)}</b></td><td>${esc(o.email)}</td><td>${esc(o.date)}</td><td>${money(o.total)}</td><td><select class="status ${o.status!=='Delivered'?'processing':''}" data-order-status="${esc(o.id)}" aria-label="Status for ${esc(o.id)}">${['Processing','Shipped','Delivered','Cancelled'].map(t=>`<option ${o.status===t?'selected':''}>${t}</option>`).join('')}</select></td><td><button class="filter-reset" data-action="order-details" data-id="${esc(o.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`}
function help(){return `<div class="wrap">${crumbs('Help & support')}<div class="page-title"><h1>A little help for your next build.</h1><p>Find answers about shopping, delivery and returns.</p></div><div class="help-grid">${[['truck','Delivery across India','Sample shipping: ₹59, or free for orders of ₹999 and above. Typical estimated delivery is 3–7 business days.'],['box','Simple returns','This preview demonstrates a 7-day return policy for unused components in their original packaging.'],['support','Product support','Need help selecting a part? Check its product specifications or email the sample address support@powerelectronics.demo.']].map(x=>`<div class="panel">${icon(x[0],30)}<h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div><section class="panel faq"><h2>Frequently asked questions</h2>${[['Is this a real store?','This is a client demonstration with sample prices, inventory and accounts. Orders do not charge money or trigger shipments.'],['How do I apply the discount?','Enter BUILD10 in the cart or checkout discount field to receive 10% off the subtotal. Delivery is calculated separately.'],['Can I test customer and admin accounts?','Yes. Use the separate Customer Login and Admin Login options at the top of the page or in the footer. Both dialogs show the demo credentials and a Fill demo credentials button.'],['Where are my changes saved?','Cart, wishlist, profile, inventory and orders are saved in this browser only. Login lasts for this browser session. Other browsers do not share this data.'],['Can this become a real store?','Yes. Launch requires a production backend, secure authentication, verified product data, approved images, delivery rules and a payment provider.']].map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</section></div>`}
function route(){const [path,query='']=(location.hash.slice(1)||'/').split('?');return {path,q:new URLSearchParams(query)}}
function render(){const {path,q}=route();let html;if(path==='/')html=home();else if(path==='/shop')html=shop(q);else if(path.startsWith('/product/'))html=detail(path.split('/')[2]);else if(path==='/cart')html=cartPage();else if(path==='/checkout')html=checkout();else if(path.startsWith('/success/'))html=success(path.split('/')[2]);else if(path==='/account')html=account();else if(path==='/admin')html=admin();else if(path==='/bulk-orders')html=customerBulkPage();else if(path==='/admin/bulk-orders')html=adminBulkPage();else if(path==='/admin/settings')html=settingsPage();else if(path==='/notifications')html=notificationsPage();else if(path==='/stock-requests'||path==='/admin/stock-requests')html=stockRequestsPage();else if(path==='/admin/pricing')html=pricingPage();else if(path==='/admin/price-history')html=priceHistoryPage();else if(path==='/admin/upload')html=uploadPage();else if(path==='/admin/uploads')html=uploadsPage();else if(path==='/login/customer')html=loginPage('customer');else if(path==='/login/admin')html=loginPage('admin');else if(path==='/wishlist')html=`<div class="wrap">${crumbs('Wishlist')}<div class="page-title"><h1>Saved for your next idea.</h1><p>Your favourite components, ready when you are.</p></div>${wishlist.length?`<div class="products">${products.filter(p=>p.active!==false&&wishlist.includes(p.id)).map(card).join('')}</div>`:empty('Nothing saved yet','Tap the heart on a product to keep it here.')}</div>`;else if(path==='/help')html=help();else html=`<div class="wrap">${crumbs('Page not found')}${empty('This page isn’t available','Find the components you need in our catalog.')}</div>`;$('#app').innerHTML=html;updateHeader();$('#search').value=q.get('q')||'';document.title=path==='/'?'Power Electronics — Build something brilliant':`${path==='/shop'?'Shop components':path==='/admin'?'Store administration':path.startsWith('/product/')?product(path.split('/')[2])?.name||'Product':path.split('/')[1]?.replace(/^./,c=>c.toUpperCase())} — Power Electronics`}
function navigate(path){if(location.hash==='#'+path){render();window.scrollTo(0,0)}else location.hash=path}
window.addEventListener('hashchange',()=>{detailQty=1;render();window.scrollTo({top:0,behavior:'instant'});const heading=$('#app h1')||$('#app h2');if(heading?.focus){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}});
function closeModal(){$('#modal').close()}
function showModal(content){$('#modalcontent').innerHTML=content;$('#modal').showModal()}
function loginContent(role='customer'){const email=role==='admin'?'admin@powerelectronics.demo':'customer@powerelectronics.demo',password=role==='admin'?'Admin123!':'Customer123!';return `<div class="eyebrow">Power Electronics demo access</div><h2>${role==='admin'?'Welcome back, admin.':'Welcome back, maker.'}</h2><p>${role==='admin'?'Explore products, inventory and orders.':'Your saved ideas and orders are waiting.'}</p><form id="loginform" data-role="${role}">${field('Email address','email','','email',true)}${field('Password','password','','password',true)}<p id="loginerror" class="error" role="alert"></p><button class="btn login-submit">Sign in as ${role}</button></form><div class="demo-box"><strong>Try the ${role} account</strong>${email}<br>Password: ${password}<br><button class="demo-fill" data-action="fill-login" data-role="${role}">Fill demo credentials</button><p>Simulated access for client review. Use these sample credentials only.</p></div><button class="filter-reset" data-action="${role==='admin'?'login':'admin-login'}">${role==='admin'?'Switch to customer login':'Switch to admin login'}</button>`}
function login(role='customer'){loginReturn=route().path==='/checkout'?'/checkout':route().path==='/bulk-orders'?'/bulk-orders':route().path.startsWith('/product/')?route().path:'/account';showModal(loginContent(role))}
function loginPage(role){loginReturn='/account';return `<div class="wrap">${crumbs(role==='admin'?'Admin login':'Customer login')}<div class="login-page"><aside class="login-intro ${role==='admin'?'admin-intro':''}"><div class="eyebrow">Power Electronics</div><h1>${role==='admin'?'A clear view of your store.':'Welcome to your next great build.'}</h1><p>${role==='admin'?'Manage your catalog, track orders and keep your inventory up to date.':'Save your favourite components, track your orders and make your next idea happen.'}</p><span class="login-role-badge">${role==='admin'?'Administrator access':'Customer access'}</span></aside><section class="panel login-panel">${loginContent(role)}</section></div></div>`}
function editProduct(id){if(user?.role!=='admin')return;const p=product(id);showModal(`<h2>Edit product</h2><p>Changes update the storefront in this browser.</p><form id="editform" data-id="${p.id}">${field('Product name','name',p.name,'text',true)}<div class="form-grid">${field('Price (₹)','price',p.price,'number',true)}${field('Original price (₹)','old',p.old,'number',true)}${field('Available stock','stock',p.stock,'number',true)}</div><p id="editerror" class="error" role="alert"></p><button class="btn">Save changes</button></form>`);for(const n of ['price','old','stock'])$(`#editform [name="${n}"]`).min=n==='stock'?0:0.01;$('#editform [name="stock"]').step=1;$('#editform [name="price"]').step=0.01;$('#editform [name="old"]').step=0.01}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,change,tab,role}=b.dataset;if(action==='skip-content'){e.preventDefault();$('#app').focus();$('#app').scrollIntoView({block:'start'})}else if(action==='close')closeModal();else if(action==='account')navigate(user?.role==='admin'?'/admin':'/account');else if(action==='cart')navigate('/cart');else if(action==='share')openShare(id);else if(action==='copy-share')void copyShare();else if(action==='native-share')void nativeShare();else if(action==='card-qty')changeCardQuantity(id,Number(change));else if(action==='login'){if(route().path.startsWith('/login/'))navigate('/login/customer');else login()}else if(action==='admin-login'){if(route().path.startsWith('/login/'))navigate('/login/admin');else login('admin')}else if(action==='fill-login'){const admin=role==='admin';$('#loginform [name="email"]').value=admin?'admin@powerelectronics.demo':'customer@powerelectronics.demo';$('#loginform [name="password"]').value=admin?'Admin123!':'Customer123!'}else if(action==='logout'){user=null;sessionStorage.removeItem('circuit-demo-user');navigate('/');toast('Signed out')}else if(action==='add')addToCart(id);else if(action==='add-detail')addToCart(id,detailQty);else if(action==='wish'){const n=Number(id);wishlist=wishlist.includes(n)?wishlist.filter(i=>i!==n):[...wishlist,n];save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);toast(wishlist.includes(n)?'Saved to your wishlist':'Removed from wishlist')}else if(action==='home-tab'){homeTab=tab;const scroll=window.scrollY;render();window.scrollTo(0,scroll)}else if(action==='admin-tab'){adminTab=tab;render()}else if(action==='account-tab'){accountTab=tab;render()}else if(action==='edit-product')editProduct(id);else if(action==='detail-qty'){const limit=Math.min(99,product(route().path.split('/')[2])?.stock||1);detailQty=Math.min(limit,Math.max(1,detailQty+Number(change)));$('#detailqty').textContent=detailQty}else if(action==='cart-qty'){const item=cart.find(i=>i.id===Number(id));if(item.qty+Number(change)>Math.min(99,product(id).stock))return toast('Maximum available stock reached');item.qty+=Number(change);cart=cart.filter(i=>i.qty>0);save();render()}else if(action==='remove'){cart=cart.filter(i=>i.id!==Number(id));save();render();toast('Product removed from cart')}else if(action==='toggle-filters'){filtersOpen=!filtersOpen;const scroll=window.scrollY;render();window.scrollTo(0,scroll)}else if(action==='clear-filters')navigate('/shop');else if(action==='order-details'){if(user?.role!=='admin')return;const o=orders.find(o=>o.id===id);showModal(`<h2>Order ${esc(o.id)}</h2><p>${esc(o.email)} · ${esc(o.date)}</p>${orderCard(o)}<b>Total: ${money(o.total)}</b>`)}});
function captureCheckout(e){if(e.target.closest?.('#checkoutform'))checkoutDraft=Object.fromEntries(new FormData($('#checkoutform')))}
document.addEventListener('input',captureCheckout);
document.addEventListener('change',e=>{captureCheckout(e);const key=e.target.dataset.filter;if(key){const {q}=route();if(key==='stock'){if(e.target.checked)q.set(key,'1');else q.delete(key)}else if(e.target.value)q.set(key,e.target.value);else q.delete(key);navigate('/shop?'+q.toString())}if(e.target.dataset.orderStatus&&user?.role==='admin'){const o=orders.find(o=>o.id===e.target.dataset.orderStatus);o.status=e.target.value;save();render();toast('Order status updated')}});
document.addEventListener('submit',e=>{const f=e.target;if(!['searchform','couponform','loginform','checkoutform','profileform','editform'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(f));if(f.id==='searchform'){navigate('/shop?q='+encodeURIComponent($('#search').value.trim()))}else if(f.id==='couponform'){const code=data.code.trim().toUpperCase();if(code!=='BUILD10'&&code!=='')return toast('Code not recognised. Try BUILD10.');coupon=code;save();render();toast(code?'10% discount applied':'Discount removed')}else if(f.id==='loginform'){const admin=f.dataset.role==='admin',email=admin?'admin@powerelectronics.demo':'customer@powerelectronics.demo',pass=admin?'Admin123!':'Customer123!';if(data.email.trim().toLowerCase()!==email||data.password!==pass){$('#loginerror').textContent='Use the demo email and password shown below.';return}user={role:admin?'admin':'customer',email};sessionStorage.setItem('circuit-demo-user',JSON.stringify(user));closeModal();navigate(admin?'/admin':loginReturn);toast('Welcome to your demo account')}else if(f.id==='profileform'){profile={...profile,...data};save();render();toast('Profile saved')}else if(f.id==='editform'){if(user?.role!=='admin')return;const p=product(f.dataset.id);if(!data.name.trim()||Number(data.price)<0.01||Number(data.old)<Number(data.price)||!Number.isInteger(Number(data.stock))||Number(data.stock)<0){$('#editerror').textContent='Enter a name, positive prices, an original price at least equal to the sale price, and a whole-number stock quantity.';return}try{commitProductChanges([{id:p.id,price:Number(data.price),old:Number(data.old),stock:Number(data.stock),name:data.name.trim()}],'Individual product edit')}catch(error){$('#editerror').textContent=error.message;return};p.tag=p.old>p.price?Math.round((1-p.price/p.old)*100)+'% off':'Maker favourite';cart=cart.map(i=>({...i,qty:Math.min(i.qty,product(i.id).stock)})).filter(i=>i.qty>0);save();closeModal();render();toast('Product updated')}else if(f.id==='checkoutform'){if(!cart.length)return;if(!validPaymentMethod(data.payment)){toast('Choose an available payment method.');return}if(cart.some(i=>product(i.id).active===false||i.qty>product(i.id).stock)){render();toast('Stock changed. Review your cart.');return}checkoutDraft.payment=data.payment;const t=totals(),id='CT-'+Date.now().toString().slice(-8);const o={id,date:new Date().toISOString().slice(0,10),email:user?.role==='customer'?user.email:data.email,status:'Processing',items:cart.map(i=>({...i,name:product(i.id).name,price:product(i.id).price})),...t,address:`${data.name} · ${data.address}, ${data.city}, ${data.state} ${data.pincode}`,payment:data.payment};orders.unshift(o);for(const i of cart)product(i.id).stock-=i.qty;cart=[];coupon='';checkoutDraft={};save();navigate('/success/'+id)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
