let importBatches=read('import-batches',[]),importDrafts=read('import-drafts',[]),importSelection=new Set(),importQuery='',importStatus='all',importBatchFilter='',importBusy=false,importNotice='';
const requiredImportColumns=['sku','title','description','category','price','stock'];
const importAliases={sku:['sku','productsku','itemcode'],title:['title','name','productname','itemtitle'],description:['description','productdescription','details'],category:['category','productcategory'],price:['price','saleprice','sellingprice'],stock:['stock','quantity','inventory'],old:['compareatprice','originalprice','mrp','regularprice'],imageUrl:['imageurl','image','productimageurl']};
const referenceImageRules=[[/arduino.*mega|mega.*2560/i,3],[/arduino.*uno|uno.*r3/i,1],[/raspberry.*pi.*(?:4\b|model\s*b)/i,2],[/esp32.*(?:s3|mini)/i,5],[/esp32|esp.wroom/i,4],[/ldr|light sensor/i,6],[/ttp223|capacitive touch/i,7],[/pn532|nfc.*rfid/i,8],[/waveshare.*(?:7|seven)|7.?inch.*(?:hdmi|display)/i,9],[/12v.*5a.*(?:adapter|power)|power.*adapter.*12v/i,10],[/st.link|stm.*programmer/i,11],[/stm32.*(?:blue pill|f103)|blue pill/i,12],[/5mm.*green.*led|green.*led.*100/i,13],[/hi.watt.*9v|9v.*battery/i,14]];
function requireDemoAdmin(){if(user?.role!=='admin')throw Error('Sign in as the demo administrator first.')}
function persistImports(){const previousBatches=localStorage.getItem('circuit-demo-import-batches'),previousDrafts=localStorage.getItem('circuit-demo-import-drafts');try{localStorage.setItem('circuit-demo-import-batches',JSON.stringify(importBatches));localStorage.setItem('circuit-demo-import-drafts',JSON.stringify(importDrafts));return true}catch{try{if(previousBatches===null)localStorage.removeItem('circuit-demo-import-batches');else localStorage.setItem('circuit-demo-import-batches',previousBatches);if(previousDrafts===null)localStorage.removeItem('circuit-demo-import-drafts');else localStorage.setItem('circuit-demo-import-drafts',previousDrafts)}catch{}toast('Browser storage is full. Import changes could not be saved.');return false}}
function safeImageUrl(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)return '';const h=u.hostname.toLowerCase();if(h==='localhost'||h.endsWith('.local')||h==='127.0.0.1'||h==='[::1]'||/^\d+\.\d+\.\d+\.\d+$/.test(h))return '';return u.href}catch{return ''}}
function matchImportImage(title,description=''){let match=referenceImageRules.find(([pattern])=>pattern.test(title));if(!match&&!/raspberry.*pi.*5|esp8266/i.test(title)){const candidates=referenceImageRules.filter(([pattern])=>pattern.test(description));if(candidates.length===1)match=candidates[0]}if(match)return {assetId:match[1],imageSource:'Reference catalog',imageStatus:'matched',imageUrl:''};return {assetId:null,imageSource:'',imageStatus:'missing',imageUrl:''}}
function draftImage(d){return d.imageUrl?safeImageUrl(d.imageUrl):d.assetId?`/assets/product-${d.assetId}.webp`:''}
function importErrors(d,all=importDrafts){const errors=[];if(!/^[A-Z0-9][A-Z0-9._-]{1,63}$/i.test(d.sku||''))errors.push('SKU: use 2–64 letters, numbers, dots, hyphens or underscores.');if(!d.title?.trim())errors.push('Title is required.');if(!d.description?.trim())errors.push('Description is required.');if(!categories.some(([c])=>c===d.category))errors.push('Choose a supported category.');if(d.price===''||!Number.isFinite(Number(d.price))||Number(d.price)<=0||Number(d.price)>1000000)errors.push('Price must be greater than 0 and no more than ₹10,00,000.');if(d.stock===''||!Number.isInteger(Number(d.stock))||Number(d.stock)<0||Number(d.stock)>100000)errors.push('Stock must be a whole number between 0 and 1,00,000.');if(d.old!==''&&(!Number.isFinite(Number(d.old))||Number(d.old)<Number(d.price)))errors.push('Compare-at price must be at least the selling price.');if(all.some(x=>x.id!==d.id&&x.sku.toUpperCase()===d.sku.toUpperCase()))errors.push('Duplicate SKU in uploaded items.');if(products.some(p=>p.id!==d.publishedId&&(p.sku||`CT-${String(p.id).padStart(4,'0')}`).toUpperCase()===d.sku.toUpperCase()))errors.push('SKU already exists in the storefront.');if(d.imageUrl&&!safeImageUrl(d.imageUrl))errors.push('Image URL must be a public HTTPS address.');if(!draftImage(d)||!['matched','verified'].includes(d.imageStatus))errors.push(d.imageStatus==='checking'?'Image is still being checked.':'A verified product image is required.');return errors}
function draftState(d){if(d.status==='published')return 'published';return importErrors(d).length?'review':'ready'}
function normalizeImportRows(matrix){if(!Array.isArray(matrix)||matrix.length<2)throw Error('The worksheet must contain a header row and at least one product.');const headers=matrix[0].map(h=>String(h??'').toLowerCase().replace(/[^a-z0-9]/g,'')),mapping={};for(const [field,names] of Object.entries(importAliases)){const found=headers.flatMap((h,i)=>names.includes(h)?[i]:[]);if(found.length>1)throw Error(`More than one ${field} column was found. Use one column per field.`);mapping[field]=found[0]??-1}const missing=requiredImportColumns.filter(c=>mapping[c]<0);if(missing.length)throw Error('Missing required columns: '+missing.join(', '));const rows=matrix.slice(1).map((cells,i)=>({cells,row:i+2})).filter(({cells})=>cells.some(c=>String(c??'').trim()!==''));if(!rows.length)throw Error('No product rows were found.');if(rows.length>250)throw Error('This demo supports up to 250 products per upload. Split the file into smaller batches.');return rows.map(({cells,row})=>{const get=k=>mapping[k]<0?'':String(cells[mapping[k]]??'').trim();return {row,sku:get('sku').toUpperCase(),title:get('title').slice(0,180),description:get('description').slice(0,2000),category:get('category'),price:get('price'),stock:get('stock'),old:get('old'),imageUrl:get('imageUrl')}})}
async function verifyDraftImage(d){if(!d.imageUrl){Object.assign(d,matchImportImage(d.title,d.description));return}const url=safeImageUrl(d.imageUrl);d.assetId=null;d.imageSource='Uploaded image URL';if(!url){d.imageStatus='failed';return}d.imageUrl=url;d.imageStatus='checking';const checkedUrl=url;const okay=await new Promise(resolve=>{const image=new Image(),timer=setTimeout(()=>{image.onload=image.onerror=null;resolve(false)},8000);image.referrerPolicy='no-referrer';image.onload=()=>{clearTimeout(timer);resolve(image.naturalWidth>0&&image.naturalHeight>0)};image.onerror=()=>{clearTimeout(timer);resolve(false)};image.src=url});if(d.imageUrl===checkedUrl)d.imageStatus=okay?'verified':'failed'}
async function stageImport(matrix,filename){requireDemoAdmin();if(importBusy)throw Error('An import is already in progress.');const rows=normalizeImportRows(matrix);if(importDrafts.length+rows.length>1000)throw Error('The browser demo limit is 1,000 uploaded items.');importBusy=true;importNotice='Checking rows and matching product images…';render();try{const batchId='batch-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);const staged=rows.map((r,i)=>({...r,id:batchId+'-'+i,batchId,status:'draft',publishedId:null,assetId:null,imageStatus:'missing',imageSource:''}));for(let start=0;start<staged.length;start+=8)await Promise.all(staged.slice(start,start+8).map(verifyDraftImage));requireDemoAdmin();const batch={id:batchId,filename:filename.slice(0,150),createdAt:new Date().toISOString(),count:staged.length};const previousDrafts=importDrafts,previousBatches=importBatches;importDrafts=[...staged,...importDrafts];importBatches=[batch,...importBatches];if(!persistImports()){importDrafts=previousDrafts;importBatches=previousBatches;throw Error('Upload could not be stored. Free browser storage and try again.')}importSelection.clear();importBatchFilter=batchId;importQuery='';importStatus='all';importNotice=`${staged.length} products imported as drafts. Review the matched images before publishing.`;navigate('/admin/uploads');return staged}finally{importBusy=false;render()}}
