function uploadPage(){return importLayout(`<div class="import-page-heading"><div><div class="eyebrow">Catalog operations</div><h1>Build your catalog.</h1><p>Turn a product sheet into a reviewed, publishable catalog.</p></div><a class="btn btn-outline" href="#/admin/uploads">View uploaded items</a></div><ol class="import-steps"><li class="active"><b>1</b><div>Upload spreadsheet<small>Start with the sample template</small></div></li><li><b>2</b><div>Review & edit<small>Validate details and product images</small></div></li><li><b>3</b><div>Publish products<small>Approve visibility in the storefront</small></div></li></ol><div class="import-upload-layout"><section class="panel upload-panel"><div class="section-head"><h3>Import your product catalog</h3><span class="file-types">XLSX · XLS · CSV</span></div><form id="productuploadform"><label class="upload-drop" id="productdrop"><span class="upload-icon">${icon('box',36)}</span><strong>${importBusy?'Matching images and validating rows…':'Drop your spreadsheet here'}</strong><span>or click to browse files</span><small>Maximum 5 MB · Up to 250 products per batch</small><input id="productfile" name="file" type="file" accept=".xlsx,.xls,.csv" ${importBusy?'disabled':''}></label><p id="chosenfile" class="subtle">No file selected</p><div class="upload-form-actions"><button class="btn" ${importBusy?'disabled':''}>${importBusy?'Processing…':'Validate & preview import'}</button><span>Products are never published automatically.</span></div></form><p class="import-feedback ${importNotice.startsWith('Error:')?'error':''}" role="status">${esc(importNotice)}</p><div class="upload-guidance"><h4>What happens after upload?</h4><p>Rows are validated, then titles are matched to product photos from the reference catalog. Each item becomes an editable draft. Unmatched images need your review before publishing.</p></div></section><aside class="panel sample-panel"><div class="eyebrow">Recommended first step</div><h3>Try a sample import</h3><p>Six realistic products, with prices, stock and descriptions. All six have matching reference photos.</p><div class="sample-preview">${sampleProductMatrix.slice(1,4).map((r,i)=>`<div><img src="/assets/product-${[1,4,2][i]}.webp" alt=""><span>${esc(r[1])}<small>${esc(r[0])} · ${money(r[4])}</small></span></div>`).join('')}</div><a class="btn btn-outline" href="/samples/power-electronics-products.xlsx" download>Download Excel template</a><a class="text-link sample-csv" href="/samples/power-electronics-products.csv" download>Download CSV version</a><button class="btn" data-import-action="sample" ${importBusy?'disabled':''}>Try sample products</button><small class="subtle">Creates drafts directly so you can explore the full workflow.</small></aside></div><section class="panel import-columns"><h3>Spreadsheet format</h3><p>Use one product per row. The first sheet, or a sheet named Products, is imported.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Column</th><th>Required</th><th>Example / rule</th></tr></thead><tbody>${[['SKU','Yes','Unique product code, e.g. PE-UNO-001'],['Title','Yes','Arduino Uno R3 Development Board'],['Description','Yes','Describe the component and its use'],['Category','Yes','Use a category from the supported list below'],['Price','Yes','Positive number in INR; no currency symbols'],['Stock','Yes','Whole number, 0 or more'],['CompareAtPrice','No','Original price; must not be less than Price'],['ImageURL','No','Public HTTPS image URL; leave blank for automatic matching']].map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="supported-categories"><b>Supported categories:</b> ${categories.map(([c])=>esc(c)).join(' · ')}</p></section>${importBatches.length?`<section class="panel import-history"><div class="section-head"><h3>Recent uploads</h3><a class="text-link" href="#/admin/uploads">Review all uploaded items</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>File</th><th>Uploaded</th><th>Products</th><th>Published</th><th>Action</th></tr></thead><tbody>${importBatches.slice(0,5).map(b=>`<tr><td>${esc(b.filename)}</td><td>${new Date(b.createdAt).toLocaleString('en-IN')}</td><td>${b.count}</td><td>${importDrafts.filter(d=>d.batchId===b.id&&d.status==='published').length}</td><td><button class="filter-reset" data-import-action="batch" data-id="${b.id}">Review batch</button></td></tr>`).join('')}</tbody></table></div></section>`:''}`,'upload')}
function filteredDrafts(){return importDrafts.filter(d=>(!importBatchFilter||d.batchId===importBatchFilter)&&(importStatus==='all'||draftState(d)===importStatus)&&(!importQuery||`${d.title} ${d.sku}`.toLowerCase().includes(importQuery.toLowerCase())))}
function uploadsPage(){const ready=importDrafts.filter(d=>draftState(d)==='ready').length,review=importDrafts.filter(d=>draftState(d)==='review').length,published=importDrafts.filter(d=>d.status==='published').length,list=filteredDrafts();return importLayout(`<div class="import-page-heading"><div><div class="eyebrow">Review before publishing</div><h1>Uploaded items</h1><p>Check images, fix product details and decide what goes live.</p></div><a href="#/admin/upload" class="btn btn-outline">Upload another file</a></div>${importNotice?`<div class="saved-note" role="status">${esc(importNotice)}</div>`:''}<div class="import-metrics">${[['Total uploaded',importDrafts.length,'All import batches'],['Ready to publish',ready,'Validated with product images'],['Needs review',review,'Fix details or image matches'],['Published',published,'Visible in this browser’s store']].map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}</div><section class="panel uploaded-panel"><div class="upload-toolbar"><form id="importfilterform" class="import-search"><input name="query" value="${esc(importQuery)}" placeholder="Search title or SKU" aria-label="Search uploaded products"><button class="btn btn-outline btn-small">Search</button></form><select data-import-filter="status" aria-label="Filter upload status">${[['all','All statuses'],['ready','Ready to publish'],['review','Needs review'],['published','Published']].map(([v,t])=>`<option value="${v}" ${v===importStatus?'selected':''}>${t}</option>`).join('')}</select><select data-import-filter="batch" aria-label="Filter upload batch"><option value="">All batches</option>${importBatches.map(b=>`<option value="${b.id}" ${b.id===importBatchFilter?'selected':''}>${esc(b.filename)}</option>`).join('')}</select></div><div class="publish-toolbar"><button class="btn btn-outline btn-small" data-ops="export-issues">Download issue report</button><span>${importSelection.size} selected <span class="sep">/</span> ${list.length} items shown</span><div><button class="btn btn-outline btn-small" data-import-action="publish-selected" ${!importSelection.size?'disabled':''}>Publish selected</button><button class="btn btn-small" data-import-action="publish-ready" ${!list.some(d=>draftState(d)==='ready')?'disabled':''}>Publish ready items</button></div></div>${list.length?`<div class="table-scroll"><table class="data-table uploaded-table"><thead><tr><th><input type="checkbox" data-import-all aria-label="Select all ready products shown" ${list.filter(d=>draftState(d)==='ready').every(d=>importSelection.has(d.id))&&list.some(d=>draftState(d)==='ready')?'checked':''}></th><th>Product</th><th>Price / stock</th><th>Image</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(d=>{const errors=importErrors(d),state=draftState(d),src=['matched','verified'].includes(d.imageStatus)?draftImage(d):'';return `<tr><td><input type="checkbox" data-import-select="${d.id}" aria-label="Select ${esc(d.title||d.sku)}" ${state!=='ready'?'disabled':''} ${importSelection.has(d.id)?'checked':''}></td><td><div class="table-product">${src?`<img src="${esc(src)}" alt="${esc(d.title)}" referrerpolicy="no-referrer">`:`<span class="missing-image">${icon('box',23)}</span>`}<div><strong>${esc(d.title||'Untitled product')}</strong><small>${esc(d.sku||'SKU required')} · Row ${d.row}</small><small>${esc(d.category||'Category required')}</small></div></div></td><td><b>${d.price!==''&&Number.isFinite(Number(d.price))?money(Number(d.price)):'Price required'}</b><small>${esc(d.stock)} units</small></td><td><span class="image-state ${['matched','verified'].includes(d.imageStatus)?'check':'out'}">${({matched:'Auto-matched',verified:'URL verified',missing:'Missing image',failed:'Image failed',checking:'Checking…'})[d.imageStatus]||'Needs review'}</span><small>${esc(d.imageSource||'Add an image')}</small></td><td><span class="import-status ${state}">${state==='published'?'Published':state==='ready'?d.publishedId?'Update ready':'Ready to publish':'Needs review'}</span>${state==='review'?`<small class="row-issue">${esc(errors[0]||'Image needs review')}${errors.length>1?' +'+(errors.length-1)+' more':''}</small>`:''}</td><td><button class="filter-reset" data-import-action="edit" data-id="${d.id}">${state==='published'?'Edit published item':'Review & edit'}</button>${d.publishedId?`<a class="row-store-link" href="#/product/${d.publishedId}">View in store</a>`:''}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="import-empty">${icon('box',38)}<h3>${importDrafts.length?'No items match your filters':'Your catalog starts with a spreadsheet.'}</h3><p>${importDrafts.length?'Change the search, status or batch filters.':'Upload your product file or try the sample products to see the review workflow.'}</p><a class="btn" href="#/admin/upload">Go to Upload Excel</a></div>`}</section><p class="import-bottom-note">Publishing updates this browser’s demo storefront. Product images and details should be checked before a real launch.</p>`,'items')}
function reviewImport(id){requireDemoAdmin();const d=importDrafts.find(d=>d.id===id);if(!d)return;const errors=importErrors(d),src=['matched','verified'].includes(d.imageStatus)?draftImage(d):'';showModal(`<div class="eyebrow">${d.status==='published'?'Edit published item':'Review imported product'}</div><h2>${esc(d.sku||'New product')}</h2><p>Save changes as a draft, then publish when ready.</p><div class="import-editor-preview">${src?`<img src="${esc(src)}" alt="${esc(d.title)}" referrerpolicy="no-referrer">`:`<div class="missing-image">${icon('box',40)}</div>`}<div><b>${esc(d.title||'Title required')}</b><small>${esc(d.imageSource||'No matching image found')}</small><small>${d.imageStatus==='matched'?'Automatically matched from the reference catalog. Verify that it is the right component.':d.imageStatus==='verified'?'Image URL loaded successfully. Check its appearance and usage rights.':'Provide an image URL or choose a reference photo.'}</small></div></div>${errors.length?`<div class="import-validation"><b>Fix ${errors.length} issue${errors.length===1?'':'s'} before publishing</b><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'<div class="saved-note">All required details and the product image are ready.</div>'}<form id="importeditform" data-id="${d.id}"><div class="form-grid">${field('SKU','sku',d.sku,'text',true)}${field('Product title','title',d.title,'text',true)}<label class="field full">Description<textarea name="description" required rows="3" maxlength="2000">${esc(d.description)}</textarea></label><label class="field full">Category<select name="category" required><option value="">Select a category</option>${categories.map(([c])=>`<option ${d.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Price (INR)','price',d.price,'number',true)}${field('Compare-at price (INR)','old',d.old,'number')}${field('Stock','stock',d.stock,'number',true)}<label class="field">Reference photo<select name="assetId"><option value="">Automatic title matching</option>${baseProducts.map(p=>`<option value="${p.id}" ${!d.imageUrl&&d.assetId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field full">Image URL (op)<input type="url" name="imageUrl" value="${esc(d.imageUrl)}" placeholder="https://…" maxlength="1500"><small>Use a direct public HTTPS image URL. A URL takes priority over the reference photo.</small></label></div><p class="error" id="importediterror" role="alert"></p><div class="import-editor-actions"><button class="btn">Save draft & check image</button><button type="button" class="btn btn-outline" data-import-action="cancel-edit">Cancel</button></div></form>`);$('#modal').classList.add('import-editor');for(const n of ['price','old','stock']){const input=$(`#importeditform [name="${n}"]`);input.min=n==='stock'?0:0.01;input.step=n==='stock'?1:0.01}}
async function saveImportEdit(id,data){requireDemoAdmin();const d=importDrafts.find(d=>d.id===id);if(!d)throw Error('Uploaded product no longer exists.');const updated={...d,sku:data.sku.trim().toUpperCase(),title:data.title.trim().slice(0,180),description:data.description.trim().slice(0,2000),category:data.category,price:data.price,old:data.old,stock:data.stock,imageUrl:data.imageUrl.trim(),status:'draft'};if(!updated.imageUrl&&data.assetId){updated.assetId=Number(data.assetId);updated.imageSource='Manually selected reference photo';updated.imageStatus='matched';if(!baseProducts.some(p=>p.id===updated.assetId))throw Error('Choose a valid reference photo.')}else await verifyDraftImage(updated);requireDemoAdmin();const previous={...d};Object.assign(d,updated);if(!persistImports()){Object.assign(d,previous);throw Error('Draft could not be saved. Free browser storage and retry.')}importSelection.delete(d.id);return d}
function confirmImportPublish(ids){requireDemoAdmin();const unique=[...new Set(ids)],rows=unique.map(id=>importDrafts.find(d=>d.id===id));if(!rows.length)return toast('Select at least one ready product.');if(rows.some(d=>!d||d.status==='published'||importErrors(d).length))return toast('Some selected products need review. Fix the issues first.');showModal(`<div class="eyebrow">Publish to storefront</div><h2>Publish ${rows.length} product${rows.length===1?'':'s'}?</h2><p>These reviewed products will become visible to customers in this browser’s demo store.</p><div class="publish-list">${rows.slice(0,8).map(d=>`<div><span>${esc(d.title)}</span><b>${money(Number(d.price))}</b></div>`).join('')}${rows.length>8?`<p>And ${rows.length-8} more products.</p>`:''}</div><div class="import-editor-actions"><button class="btn" data-import-action="confirm-publish" data-ids="${unique.join(',')}">Publish now</button><button class="btn btn-outline" data-action="close">Keep as drafts</button></div>`)}
function publishImportProducts(ids){requireDemoAdmin();const rows=[...new Set(ids)].map(id=>importDrafts.find(d=>d.id===id));if(!rows.length||rows.some(d=>!d||d.status==='published'||importErrors(d).length))throw Error('Only ready, unpublished drafts can be published.');const productBackup=JSON.stringify(products),draftBackup=JSON.stringify(importDrafts);let nextId=Math.max(0,...products.map(p=>p.id))+1;for(const d of rows){const id=d.publishedId||nextId++,existing=product(id),record={id,name:d.title,sku:d.sku,category:d.category,price:Number(d.price),old:d.old===''?Number(d.price):Number(d.old),stock:Number(d.stock),rating:0,reviews:0,tag:'New arrival',desc:d.description,specs:{SKU:d.sku,Category:d.category,Description:d.description},assetId:d.assetId,imageUrl:d.imageUrl,imageSource:d.imageSource,origin:'excel-import',importDraftId:d.id};if(existing){recordPriceChange(existing,record.price,'Excel publication');Object.assign(existing,record);}else products.push(record);d.publishedId=id;d.status='published';d.publishedAt=new Date().toISOString();importSelection.delete(d.id)}cart=cart.map(i=>({...i,qty:Math.min(i.qty,product(i.id).stock)})).filter(i=>i.qty>0);try{localStorage.setItem('circuit-demo-products',JSON.stringify(products));localStorage.setItem('circuit-demo-import-drafts',JSON.stringify(importDrafts))}catch{products=JSON.parse(productBackup);importDrafts=JSON.parse(draftBackup);try{localStorage.setItem('circuit-demo-products',productBackup);localStorage.setItem('circuit-demo-import-drafts',draftBackup)}catch{}throw Error('Browser storage is full. Products were not published.')}save();persistImports();importNotice=`${rows.length} products published. They are now visible in the demo storefront.`;return rows.map(d=>d.publishedId)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-import-action]');if(!b)return;const {importAction:action,id,ids}=b.dataset;try{requireDemoAdmin();if(action==='sample'){await stageImport(sampleProductMatrix,'Sample products.xlsx')}else if(action==='batch'){importBatchFilter=id;importStatus='all';importQuery='';navigate('/admin/uploads')}else if(action==='edit')reviewImport(id);else if(action==='cancel-edit')closeModal();else if(action==='publish-selected')confirmImportPublish([...importSelection]);else if(action==='publish-ready')confirmImportPublish(filteredDrafts().filter(d=>draftState(d)==='ready').map(d=>d.id));else if(action==='confirm-publish'){publishImportProducts(ids.split(','));closeModal();render();toast('Products published to the storefront')}}catch(error){importNotice='Error: '+error.message;if(action==='sample')render();toast(error.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['productuploadform','importeditform','importfilterform'].includes(form.id))return;e.preventDefault();try{requireDemoAdmin();if(form.id==='productuploadform'){await readProductFile($('#productfile').files[0])}else if(form.id==='importfilterform'){importQuery=new FormData(form).get('query').trim();render()}else{const button=form.querySelector('button[type="submit"]')||form.querySelector('button');button.disabled=true;button.textContent='Checking image…';const data=Object.fromEntries(new FormData(form));await saveImportEdit(form.dataset.id,data);closeModal();render();toast('Draft saved. Review and publish when ready.')}}catch(error){if(form.id==='importeditform'){$('#importediterror').textContent=error.message;const button=form.querySelector('button');button.disabled=false;button.textContent='Save draft & check image'}else{importNotice='Error: '+error.message;render();toast(error.message)}}});
document.addEventListener('change',e=>{if(e.target.id==='productfile')$('#chosenfile').textContent=e.target.files[0]?`${e.target.files[0].name} · ${(e.target.files[0].size/1024).toFixed(1)} KB`:'No file selected';if(e.target.dataset.importSelect){if(e.target.checked)importSelection.add(e.target.dataset.importSelect);else importSelection.delete(e.target.dataset.importSelect);render()}if(e.target.hasAttribute?.('data-import-all')){for(const d of filteredDrafts().filter(d=>draftState(d)==='ready'))if(e.target.checked)importSelection.add(d.id);else importSelection.delete(d.id);render()}if(e.target.dataset.importFilter){if(e.target.dataset.importFilter==='status')importStatus=e.target.value;else importBatchFilter=e.target.value;render()}});
document.addEventListener('dragover',e=>{if(e.target.closest?.('#productdrop')){e.preventDefault();$('#productdrop').classList.add('dragging')}});document.addEventListener('dragleave',e=>{if(e.target.closest?.('#productdrop'))$('#productdrop').classList.remove('dragging')});document.addEventListener('drop',async e=>{if(!e.target.closest?.('#productdrop'))return;e.preventDefault();try{await readProductFile(e.dataTransfer.files[0])}catch(error){importNotice='Error: '+error.message;render();toast(error.message)}});
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('import-editor'));

if(document.modelContext?.registerTool){const context=document.modelContext;for(const tool of [{name:'search_products',title:'Search Power Electronics products',description:'Search the sample electronics catalog; does not change cart or orders.',annotations:{readOnlyHint:true},inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},execute(input){if(typeof input?.query!=='string')throw Error('query must be a string');return products.filter(p=>p.active!==false&&`${p.name} ${p.category}`.toLowerCase().includes(input.query.toLowerCase())).map(({id,name,price,stock})=>({id,name,price,stock}))}},{name:'add_demo_product_to_cart',title:'Add sample product to cart',description:'Add an available sample product to the visible demo cart. Does not place an order.',annotations:{readOnlyHint:false},inputSchema:{type:'object',properties:{productId:{type:'integer'},quantity:{type:'integer',minimum:1,maximum:99}},required:['productId','quantity'],additionalProperties:false},execute(input){if(!Number.isInteger(input?.productId))throw Error('productId must be an integer');if(!addToCart(input.productId,input.quantity))throw Error('Insufficient stock');return {cart:cart.map(i=>({...i})),total:totals().total}}}]){try{Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}}
